package com.acme.functions;

import javax.inject.Inject;
import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.core.Response;
import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.util.Enumeration;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;
import org.jboss.resteasy.plugins.providers.multipart.MultipartFormDataInput;
import org.jboss.resteasy.plugins.providers.multipart.InputPart;
import software.amazon.awssdk.services.s3.S3Client;
import software.amazon.awssdk.services.s3.model.PutObjectRequest;
import software.amazon.awssdk.core.sync.RequestBody;
import org.eclipse.microprofile.config.inject.ConfigProperty;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.List;
import java.util.UUID;

@Path("/api/extract")
public class ZipExtractorHandler {

    @Inject
    S3Client s3Client;

    @ConfigProperty(name = "app.upload.bucket")
    String uploadBucket;

    @ConfigProperty(name = "app.extract.dir", defaultValue = "/tmp/extractions")
    String extractDir;

    @POST
    public Response handleZipUpload(MultipartFormDataInput input) {
        try {
            List<InputPart> parts = input.getFormDataMap().get("file");
            if (parts == null || parts.isEmpty()) {
                return Response.status(400).entity("No file provided").build();
            }

            InputPart filePart = parts.get(0);
            InputStream is = filePart.getBody(InputStream.class, null);

            String sessionId = UUID.randomUUID().toString();
            File tempZip = File.createTempFile("upload-" + sessionId, ".zip");
            Files.copy(is, tempZip.toPath(), java.nio.file.StandardCopyOption.REPLACE_EXISTING);

            String outputDir = extractDir + "/" + sessionId;
            new File(outputDir).mkdirs();

            int fileCount = extractZipContents(tempZip, outputDir);

            // Upload extracted files to S3 for downstream processing
            uploadExtractedFiles(outputDir, sessionId);

            tempZip.delete();
            return Response.ok("{\"extracted\": " + fileCount + ", \"session\": \"" + sessionId + "\"}").build();
        } catch (Exception e) {
            return Response.status(500).entity("Extraction failed: " + e.getMessage()).build();
        }
    }

    private int extractZipContents(File zipFile, String destDir) throws Exception {
        int count = 0;
        try (java.util.zip.ZipInputStream zis = new java.util.zip.ZipInputStream(
                new java.io.FileInputStream(zipFile))) {
            ZipEntry entry;
            byte[] buffer = new byte[4096];

            while ((entry = zis.getNextEntry()) != null) {
                // Construct output path - NOTE: entry.getName() is used directly
                String filePath = destDir + File.separator + entry.getName();

                if (entry.isDirectory()) {
                    new File(filePath).mkdirs();
                } else {
                    // Ensure parent directories exist
                    new File(filePath).getParentFile().mkdirs();

                    try (BufferedOutputStream bos = new BufferedOutputStream(
                            new FileOutputStream(filePath))) {
                        int len;
                        while ((len = zis.read(buffer)) > 0) {
                            bos.write(buffer, 0, len);
                        }
                    }
                    count++;
                }
                zis.closeEntry();
            }
        }
        return count;
    }

    private void uploadExtractedFiles(String dirPath, String sessionId) throws Exception {
        File dir = new File(dirPath);
        if (!dir.exists()) return;

        File[] files = dir.listFiles();
        if (files == null) return;

        for (File file : files) {
            if (file.isFile()) {
                String key = "extractions/" + sessionId + "/" + file.getName();
                s3Client.putObject(
                    PutObjectRequest.builder()
                        .bucket(uploadBucket)
                        .key(key)
                        .build(),
                    RequestBody.fromFile(file)
                );
            } else if (file.isDirectory()) {
                uploadExtractedFiles(file.getAbsolutePath(), sessionId + "/" + file.getName());
            }
        }
    }
}
